package connect

// ResultOf computes the winner of a game of Hex (Polygon / CON-TAC-TIX).
//
// The board is supplied as a slice of strings, one string per row, where each
// character is a cell: 'X', 'O', or '.' for an empty cell. The rows together
// describe a parallelogram of hexagonal cells in which each successive row is
// shifted one cell to the right.
//
// Player 'X' is assigned the left and right sides and wins by connecting them;
// player 'O' is assigned the top and bottom sides and wins by connecting them.
// The returned string is "X" or "O" if that player has won, or "" if the game
// is not yet decided.
func ResultOf(lines []string) (string, error) {
	rows := len(lines)
	if rows == 0 {
		return "", nil
	}

	board := make([][]byte, rows)
	cols := 0
	for r, l := range lines {
		board[r] = []byte(l)
		if len(l) > cols {
			cols = len(l)
		}
	}

	// Player X plays from left to right.
	if connects(board, 'X',
		func(r, c int) bool { return c == 0 },
		func(r, c int) bool { return c == cols-1 },
	) {
		return "X", nil
	}
	// Player O plays from top to bottom.
	if connects(board, 'O',
		func(r, c int) bool { return r == 0 },
		func(r, c int) bool { return r == rows-1 },
	) {
		return "O", nil
	}
	return "", nil
}

// connects reports whether the given player has a connected chain of cells that
// begins at a cell matching isStart and reaches a cell matching isTarget.
func connects(board [][]byte, player byte, isStart, isTarget func(r, c int) bool) bool {
	rows := len(board)
	visited := make([][]bool, rows)
	for r := range board {
		visited[r] = make([]bool, len(board[r]))
	}

	var queue [][2]int
	for r := 0; r < rows; r++ {
		for c := 0; c < len(board[r]); c++ {
			if board[r][c] == player && isStart(r, c) {
				visited[r][c] = true
				queue = append(queue, [2]int{r, c})
			}
		}
	}

	// The six hexagonal neighbours of a cell. Because each row of the
	// parallelogram is shifted one cell to the right, the two cells in the row
	// below sit at columns c-1 and c, and the two in the row above at c and c+1.
	offsets := [][2]int{
		{0, -1}, {0, 1},   // same row
		{1, -1}, {1, 0},   // row below
		{-1, 0}, {-1, 1},  // row above
	}

	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		r, c := cur[0], cur[1]
		if isTarget(r, c) {
			return true
		}
		for _, o := range offsets {
			nr, nc := r+o[0], c+o[1]
			if nr < 0 || nr >= rows || nc < 0 || nc >= len(board[nr]) {
				continue
			}
			if visited[nr][nc] || board[nr][nc] != player {
				continue
			}
			visited[nr][nc] = true
			queue = append(queue, [2]int{nr, nc})
		}
	}
	return false
}

